// Schema-driven field derivation for the editable inspector (Phase 6 Wave 2).
//
// The inspector edits a component by writing its *whole* value back with `component.set` (the wire
// takes the full component, never a patch). This module is the pure bridge between a component's
// JSON Schema — as `engine.describe` reports it, generated by Rust `schemars` v1 — and the widget
// forms the inspector renders: it turns a schema + current value into a flat list of typed field
// descriptors, and it reassembles the full value from a single field edit. It is transport-free and
// React-free so the whole mapping is unit-testable (see inspect-fields.test.ts).
//
// # What the real schemars output looks like (verified against crates/ludion-engine/src/components.rs)
//
// schemars v1 emits draft-2020-12 schemas. The shapes this module handles, exactly as the engine
// produces them:
//   - a struct  → `{ "type": "object", "properties": { … } }` (Transform, Sprite, Camera, …)
//   - a newtype → the inner scalar, e.g. `Name(String)` → `{ "type": "string" }` (NO properties:
//     the whole component value is a bare string, so it becomes a single field at the empty path)
//   - `[f32; N]` → `{ "type": "array", "items": { "type": "number", "format": "float" },
//     "minItems": N, "maxItems": N }`  (fixed numeric vector — NOT `prefixItems`)
//   - `Option<String>` → `{ "type": ["string", "null"] }`  (a nullable string)
//   - `bool` → `{ "type": "boolean" }`, `f32` → `{ "type": "number", "format": "float" }`
//   - a bounded number → the above plus `"minimum"`/`"maximum"` (from `#[schemars(range(…))]`), and
//     optionally `"x-ui-range": [lo, hi]` (from `#[schemars(extend(…))]`) — an inert extension
//     keyword naming how far a slider should *travel*, as opposed to what the scene validator will
//     accept. On a fixed numeric array the bounds sit on `items` (they are per element, which is how
//     `x-ui-range` is read too), but `x-ui-range` itself sits on the array node.
//   - a unit enum (Primitive) → a property `$ref`-ing `#/$defs/Primitive`, whose def is
//     `{ "type": "string", "enum": [ … ] }`
//   - an internally-tagged enum (Projection) → a `$ref` to a `#/$defs/…` def that is a `oneOf`
// Enums, `anyOf`/`allOf`, `const`, and nested structs all fall to the raw-JSON widget — the deliberate
// "shape we don't cleanly widget" bucket. `oneOf` gets one narrow exception (see `deriveVariantOptions`
// below): bare-string unit variants (`{"type":"string","const":"cube"}`, one branch per value), alone
// (a plain unit enum like `Collider.body` — Phase 12 Wave 5) or mixed with one or more
// single-string-property object variants (`{"asset": "…"}`, `{"voxel": "…"}`, Mesh's `MeshSource` —
// Phase 8 Wave 2, generalized to N object variants in Phase 10 Wave 5), become a dropdown widget
// (plus a text input when an object variant is selected). A `oneOf` of object variants alone (no unit
// branch at all) still falls to raw JSON, same as any other unsupported shape.

/** A path into a component value: object keys (strings) and array indices (numbers). The empty path
 *  addresses the whole value (used for scalar newtype components like `Name`). */
export type FieldPath = readonly (string | number)[];

/** What a numeric field's schema says about its size: how far a slider may travel, and where the
 *  scene validator's legal bounds are. The two are independent — a field can declare a useful travel
 *  range and no legal bound, or a legal bound and no travel. */
export interface FieldRange {
  /** Slider travel. */
  readonly min: number;
  readonly max: number;
  /** Validation bounds where the schema declares them; a dragged value is clamped to these. */
  readonly hardMin: number | null;
  readonly hardMax: number | null;
}

/** A single numeric field (`f32`/`i32`) rendered as one text input parsed on commit. */
export interface NumberField {
  readonly kind: 'number';
  readonly path: FieldPath;
  readonly label: string;
  /** True for JSON Schema `integer`: a fractional draft is rejected on commit. */
  readonly integer: boolean;
  /** `null` when the schema states no usable travel: the field is a plain number box. */
  readonly range: FieldRange | null;
}

/** A boolean field rendered as a checkbox (committed immediately — it has no in-progress draft). */
export interface BooleanField {
  readonly kind: 'boolean';
  readonly path: FieldPath;
  readonly label: string;
}

/** A string field. `nullable` (from `["string","null"]`, i.e. an `Option<String>`) means an empty
 *  draft commits as `null` rather than `""`. */
export interface StringField {
  readonly kind: 'string';
  readonly path: FieldPath;
  readonly label: string;
  readonly nullable: boolean;
}

/** A fixed-length numeric array (a vector like `[f32;3]`, or an RGBA color) rendered as `length`
 *  number inputs. `color` marks a 3/4-wide field whose name reads as a color, so the UI may show a
 *  non-interactive swatch. */
export interface VectorField {
  readonly kind: 'vector';
  readonly path: FieldPath;
  readonly label: string;
  readonly length: number;
  readonly integer: boolean;
  readonly color: boolean;
  /** Understood per element (every component of a vector shares one range); `null` when the schema
   *  states no usable travel. */
  readonly range: FieldRange | null;
}

/** The fallback: anything the schema doesn't cleanly describe (enums, `oneOf`, nested structs,
 *  nullable non-strings, unknown shapes). Rendered as a raw-JSON textarea, validated on commit. */
export interface JsonField {
  readonly kind: 'json';
  readonly path: FieldPath;
  readonly label: string;
}

/** One choice in a {@link VariantField}: either a bare-string unit variant (commits that literal
 *  string), or an object variant (commits `{ [property]: <text> }`). Multiple `'asset'`-kind options
 *  can appear in one field's `options` (e.g. `MeshSource`'s `asset` and `voxel` variants); each carries
 *  its own `property`, and `deriveVariantOptions` guarantees those properties are pairwise distinct so
 *  a value can never match more than one. */
export type VariantOption =
  | { readonly kind: 'unit'; readonly value: string }
  | { readonly kind: 'asset'; readonly property: string };

/** A `oneOf` of unit-string variants plus zero or more single-string-property object variants (e.g.
 *  `MeshSource`: `"cube" | "plane" | "sphere" | { asset: string } | { voxel: string }`, or the
 *  unit-only `Body`: `"static" | "dynamic"`) — serde external tagging where unit variants serialize
 *  bare and each data-carrying variant serializes as a small single-key object. Rendered as a
 *  dropdown (variant choice) plus, when an object variant is selected, a text input for its one
 *  property. `options` is always non-empty and always contains at least one unit variant. */
export interface VariantField {
  readonly kind: 'variant';
  readonly path: FieldPath;
  readonly label: string;
  readonly options: readonly VariantOption[];
}

export type FieldDescriptor =
  | NumberField
  | BooleanField
  | StringField
  | VectorField
  | JsonField
  | VariantField;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/** Resolves the value at a JSON Pointer (`/$defs/Primitive`) under `root`, or `undefined`. */
function pointerGet(root: unknown, pointer: string): unknown {
  if (pointer === '') {
    return root;
  }
  const parts = pointer
    .split('/')
    .slice(1)
    .map((p) => p.replace(/~1/g, '/').replace(/~0/g, '~'));
  let cur: unknown = root;
  for (const part of parts) {
    if (Array.isArray(cur)) {
      cur = cur[Number(part)];
    } else if (isRecord(cur)) {
      cur = cur[part];
    } else {
      return undefined;
    }
    if (cur === undefined) {
      return undefined;
    }
  }
  return cur;
}

/** Chases local `$ref`s (`#/$defs/…`, `#/definitions/…`) against `root`, bounded so a cyclic
 *  reference cannot hang the walk. An unresolvable ref is returned as-is (the caller falls back). */
function resolveRef(node: unknown, root: unknown, depth = 0): unknown {
  if (depth >= 16 || !isRecord(node)) {
    return node;
  }
  const ref = node.$ref;
  if (typeof ref !== 'string' || !ref.startsWith('#')) {
    return node;
  }
  const target = pointerGet(root, ref.slice(1));
  if (target === undefined) {
    return node;
  }
  return resolveRef(target, root, depth + 1);
}

/** The JSON Schema `type` keyword as a list of type names, or `null` when absent/malformed. */
function typeNames(schema: Record<string, unknown>): readonly string[] | null {
  const type = schema.type;
  if (typeof type === 'string') {
    return [type];
  }
  if (Array.isArray(type)) {
    return type.filter((t): t is string => typeof t === 'string');
  }
  return null;
}

function finiteNumber(value: unknown): number | null {
  return typeof value === 'number' && Number.isFinite(value) ? value : null;
}

/** The `x-ui-range: [lo, hi]` travel keyword, or `null` when it is absent or does not describe a
 *  usable track (wrong length, non-finite, `lo >= hi`) — an unknown keyword nobody validates, so a
 *  malformed one must degrade to a plain number box rather than produce a broken slider. */
function travelKeyword(schema: Record<string, unknown>): readonly [number, number] | null {
  const raw = schema['x-ui-range'];
  if (!Array.isArray(raw) || raw.length !== 2) {
    return null;
  }
  const lo = finiteNumber(raw[0]);
  const hi = finiteNumber(raw[1]);
  return lo !== null && hi !== null && lo < hi ? [lo, hi] : null;
}

/** The range of a numeric field. `travel` is the node carrying `x-ui-range`, `bounds` the node
 *  carrying `minimum`/`maximum` — the same node for a scalar, the array and its `items` for a vector.
 *  Travel is the declared useful range, else the legal one when it is fully stated, else nothing: a
 *  field bounded on one side only (`minimum: 0`) has no track to draw. */
function deriveRange(
  travel: Record<string, unknown>,
  bounds: Record<string, unknown>,
): FieldRange | null {
  const hardMin = finiteNumber(bounds.minimum);
  const hardMax = finiteNumber(bounds.maximum);
  const declared = travelKeyword(travel);
  const legal = hardMin !== null && hardMax !== null && hardMin < hardMax ? [hardMin, hardMax] : null;
  const track = declared ?? legal;
  return track === null ? null : { min: track[0], max: track[1], hardMin, hardMax };
}

/** Whether a `length`-wide numeric field named `label` reads as a color (so a swatch is meaningful). */
function isColorish(label: string, length: number): boolean {
  return (length === 3 || length === 4) && /colou?r/i.test(label);
}

/** The one string value a unit-variant branch names, from either `const` (what schemars v1 actually
 *  emits for `MeshSource`) or a single-entry `enum` (schemars can emit this shape too, and older/other
 *  generators do) — `null` if the branch names zero or more than one value. */
function singleStringValue(branch: Record<string, unknown>): string | null {
  if (typeof branch.const === 'string') {
    return branch.const;
  }
  if (Array.isArray(branch.enum) && branch.enum.length === 1 && typeof branch.enum[0] === 'string') {
    return branch.enum[0];
  }
  return null;
}

/** Recognises the narrow `oneOf` shape a {@link VariantField} can widget: every branch is either a
 *  bare-string unit variant, or an object branch with exactly one required string property and no
 *  others (`additionalProperties: false` is not required — the widget only ever writes that one
 *  property, so extra declared ones would just never round-trip through this form; that's already true
 *  of every other widget here). Any number of object branches is supported, provided their properties
 *  are pairwise distinct (a repeated property would make a value ambiguous between two dropdown
 *  choices) — **but at least one bare-string unit branch must be present**: a `oneOf` of object
 *  variants alone isn't a shape this widget models, and is left to the raw-JSON fallback like any
 *  other unsupported `oneOf` (e.g. `Projection`'s struct variants, or `Collider.shape`'s
 *  number/array-payload variants). Object branches are optional: a `oneOf` of unit branches alone —
 *  what schemars emits for a plain unit enum with per-variant doc comments, e.g. `Collider.body`
 *  (`static`/`dynamic`, Phase 12 Wave 5) — is a plain dropdown with no text input. Returns `null` for
 *  anything outside this shape (a non-string/optional/duplicate property, a non-object/non-string
 *  branch, no unit branch, …), which sends the field to the raw JSON fallback — never a crash, never
 *  a dropped field. */
function deriveVariantOptions(oneOf: readonly unknown[], root: unknown): readonly VariantOption[] | null {
  const options: VariantOption[] = [];
  const seenProperties = new Set<string>();
  let sawUnit = false;
  for (const raw of oneOf) {
    const branch = resolveRef(raw, root);
    if (!isRecord(branch)) {
      return null;
    }
    const types = typeNames(branch);
    if (types?.length === 1 && types[0] === 'string') {
      const value = singleStringValue(branch);
      if (value === null) {
        return null;
      }
      options.push({ kind: 'unit', value });
      sawUnit = true;
      continue;
    }
    if (types?.length === 1 && types[0] === 'object') {
      if (!isRecord(branch.properties)) {
        return null;
      }
      const propNames = Object.keys(branch.properties);
      const required = Array.isArray(branch.required) ? branch.required : [];
      if (propNames.length !== 1 || required.length !== 1 || required[0] !== propNames[0]) {
        return null;
      }
      const propSchema = resolveRef(branch.properties[propNames[0]], root);
      const propTypes = isRecord(propSchema) ? typeNames(propSchema) : null;
      if (propTypes === null || propTypes.length !== 1 || propTypes[0] !== 'string') {
        return null;
      }
      if (seenProperties.has(propNames[0])) {
        return null; // two object variants writing the same property: an ambiguous commit target
      }
      seenProperties.add(propNames[0]);
      options.push({ kind: 'asset', property: propNames[0] });
      continue;
    }
    return null;
  }
  return sawUnit ? options : null;
}

/** Derives the descriptor for one subschema at `path`/`label`. `root` is the component schema (where
 *  `$ref`s and `$defs` live). Anything not cleanly a number/bool/string/fixed-numeric-array becomes a
 *  `json` fallback. */
function deriveField(
  subschema: unknown,
  path: FieldPath,
  label: string,
  root: unknown,
): FieldDescriptor {
  const json: JsonField = { kind: 'json', path, label };
  const resolved = resolveRef(subschema, root);
  if (!isRecord(resolved)) {
    return json;
  }

  // `oneOf` gets one narrow exception before falling to raw JSON: the unit-variants-plus-object-
  // variants shape (see `deriveVariantOptions`) becomes a proper dropdown widget.
  if (resolved.oneOf !== undefined) {
    const options = Array.isArray(resolved.oneOf) ? deriveVariantOptions(resolved.oneOf, root) : null;
    return options !== null ? { kind: 'variant', path, label, options } : json;
  }

  // Shapes we deliberately never widget: enums, alternations, fixed constants. Send them to raw JSON.
  if (
    resolved.enum !== undefined ||
    resolved.const !== undefined ||
    resolved.anyOf !== undefined ||
    resolved.allOf !== undefined
  ) {
    return json;
  }

  const types = typeNames(resolved);
  if (types === null) {
    return json;
  }
  const nullable = types.includes('null');
  const nonNull = types.filter((t) => t !== 'null');
  if (nonNull.length !== 1) {
    return json; // a genuine union (or nothing but null): not a single widget
  }
  const type = nonNull[0];

  switch (type) {
    case 'boolean':
      // A nullable boolean has no clean single-checkbox form.
      return nullable ? json : { kind: 'boolean', path, label };
    case 'integer':
    case 'number':
      return nullable
        ? json
        : {
            kind: 'number',
            path,
            label,
            integer: type === 'integer',
            range: deriveRange(resolved, resolved),
          };
    case 'string':
      return { kind: 'string', path, label, nullable };
    case 'array': {
      // A fixed-length numeric array is a vector/color; everything else (variable length, non-numeric,
      // or per-index `prefixItems`) is not something these widgets model.
      if (nullable) {
        return json;
      }
      const min = resolved.minItems;
      const max = resolved.maxItems;
      const items = resolveRef(resolved.items, root);
      if (
        typeof min !== 'number' ||
        typeof max !== 'number' ||
        min !== max ||
        min < 1 ||
        !isRecord(items)
      ) {
        return json;
      }
      const itemTypes = typeNames(items);
      const itemType = itemTypes?.length === 1 ? itemTypes[0] : null;
      if ((itemType !== 'number' && itemType !== 'integer') || items.enum !== undefined) {
        return json;
      }
      return {
        kind: 'vector',
        path,
        label,
        length: min,
        integer: itemType === 'integer',
        color: isColorish(label, min),
        range: deriveRange(resolved, items),
      };
    }
    default:
      return json;
  }
}

/**
 * Derives the flat list of editable fields for a component from its JSON Schema and current value.
 *
 * A struct schema (`{ type: object, properties }`) yields one field per property, in schema order.
 * A scalar/newtype schema (like `Name` → `string`) yields a single field at the empty path (the whole
 * component value). Any object key present in `value` but absent from `properties` is appended as a
 * raw-JSON field so nothing an entity actually carries is silently uneditable.
 */
export function deriveFields(schema: unknown, value: unknown): readonly FieldDescriptor[] {
  const root = schema;
  const resolved = resolveRef(schema, root);

  if (isRecord(resolved) && isRecord(resolved.properties)) {
    const properties = resolved.properties;
    const fields: FieldDescriptor[] = Object.keys(properties).map((key) =>
      deriveField(properties[key], [key], key, root),
    );
    // Surface any stray keys the schema doesn't declare (defensive; the built-ins never emit them).
    if (isRecord(value)) {
      for (const key of Object.keys(value)) {
        if (!(key in properties)) {
          fields.push({ kind: 'json', path: [key], label: key });
        }
      }
    }
    return fields;
  }

  // A scalar/newtype component (or an unrecognised schema): the whole value is one field.
  return [deriveField(resolved, [], '', root)];
}

/** Reads the value at `path` within `value` (`undefined` if any step is missing). */
export function valueAtPath(value: unknown, path: FieldPath): unknown {
  let cur: unknown = value;
  for (const key of path) {
    if (Array.isArray(cur)) {
      cur = cur[Number(key)];
    } else if (isRecord(cur)) {
      cur = cur[String(key)];
    } else {
      return undefined;
    }
  }
  return cur;
}

/**
 * Produces the full component value with the single field at `fieldPath` replaced by `newFieldValue`.
 *
 * Containers along the path are cloned (never mutated), so the caller's current value is untouched —
 * the result is what goes on the wire as `component.set { value }`. An empty path replaces the whole
 * value (a scalar component like `Name`). Missing containers are created from the next path step's
 * kind (numeric → array, string → object), so a value assembled from a partial current value still
 * lands in the right shape.
 */
export function applyFieldEdit(
  currentValue: unknown,
  fieldPath: FieldPath,
  newFieldValue: unknown,
): unknown {
  if (fieldPath.length === 0) {
    return newFieldValue;
  }
  const [head, ...rest] = fieldPath;
  if (typeof head === 'number') {
    const array = Array.isArray(currentValue) ? [...currentValue] : [];
    array[head] = applyFieldEdit(array[head], rest, newFieldValue);
    return array;
  }
  const object: Record<string, unknown> = isRecord(currentValue) ? { ...currentValue } : {};
  object[head] = applyFieldEdit(object[head], rest, newFieldValue);
  return object;
}
